function errorMessage(e: unknown) { return e instanceof Error ? e.message : 'ดำเนินการไม่สำเร็จ'; }
async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, { ...init, cache: 'no-store', headers: { ...(init?.body instanceof FormData ? {} : { 'Content-Type': 'application/json' }), ...init?.headers } });
  let data: unknown; try { data = await response.json(); } catch { throw new Error('เซิร์ฟเวอร์ไม่ตอบกลับ กรุณาลองใหม่'); }
  if (!response.ok) { const message = data && typeof data === 'object' && 'error' in data && typeof data.error === 'string' ? data.error : `เกิดข้อผิดพลาด (${response.status})`; const err = new Error(message) as Error & { status: number }; err.status = response.status; throw err; } return data as T;
}
function Banner({ children, kind = 'info' }: { children: React.ReactNode; kind?: 'info' | 'warn' | 'good' }) { return <div className={`notice ${kind}`}>{kind === 'warn' ? <TriangleAlert size={17} /> : kind === 'good' ? <CheckCircle2 size={17} /> : <Info size={17} />}<div>{children}</div></div>; }
function Empty({ icon: Icon = ClipboardList, title, children, action }: { icon?: typeof ClipboardList; title: string; children: React.ReactNode; action?: React.ReactNode }) { return <div className="empty-state"><div className="empty-icon"><Icon size={28} /></div><h3>{title}</h3><p>{children}</p>{action}</div>; }
function Modal({ title, subtitle, children, onClose, wide = false }: { title: string; subtitle?: string; children: React.ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLElement>(null); const closeRef = useRef(onClose); closeRef.current = onClose;
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const focusable = () => Array.from(dialog.current?.querySelectorAll<HTMLElement>('button:not(:disabled), a[href], input:not(:disabled), select:not(:disabled), textarea:not(:disabled), [tabindex="0"]') || []).filter(el => el.offsetParent !== null);
    focusable()[0]?.focus();
    const fn = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { e.preventDefault(); closeRef.current(); }
      if (e.key !== 'Tab') return;
      const elements = focusable(); const first = elements[0]; const last = elements[elements.length - 1];
      if (!first) { e.preventDefault(); dialog.current?.focus(); }
      else if (e.shiftKey && (document.activeElement === first || !dialog.current?.contains(document.activeElement))) { e.preventDefault(); last.focus(); }
      else if (!e.shiftKey && (document.activeElement === last || !dialog.current?.contains(document.activeElement))) { e.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', fn); const old = document.body.style.overflow; document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', fn); document.body.style.overflow = old; if (previous?.isConnected) previous.focus(); };
  }, []);
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><section ref={dialog} tabIndex={-1} role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide ? 'wide' : ''}`}><header className="modal-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div><button className="icon-button" aria-label="ปิด" onClick={onClose}><X size={22} /></button></header>{children}</section></div>;
}
function Kpi({ label, value, unit, detail, icon: Icon, tone = 'green' }: { label: string; value: string; unit?: string; detail: string; icon: typeof Trees; tone?: string }) { return <div className="kpi"><div className="kpi-label">{label}<span className={`kpi-icon ${tone}`}><Icon size={19} /></span></div><div className="kpi-value">{value}<span>{unit}</span></div><div className="kpi-detail">{detail}</div></div>; }
function SectionHead({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) { return <div className="section-head"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>; }
function CsvButton({ roundId, type = 'csv', children, publicReadOnly = false }: { roundId?: string; type?: 'csv' | 'json'; children?: React.ReactNode; publicReadOnly?: boolean }) { return <a className="button secondary small" href={publicReadOnly ? `./baseline.${type}` : `/api/export?type=${type}${roundId ? '&roundId=' + encodeURIComponent(roundId) : ''}`} download><Download size={15} />{children || (type === 'csv' ? 'ส่งออก CSV' : 'ข้อมูล JSON')}</a>; }
function EditorLink({ editorUrl, children = 'บันทึกผลสำรวจ', className = 'button primary' }: { editorUrl: string; children?: React.ReactNode; className?: string }) { return <a className={className} href={`${editorUrl}#rounds`} target="_top"><ClipboardList size={17} />{children}<ArrowUpRight size={15} /></a>; }

export default function MrvApp({ publicReadOnly = false, editorUrl = DEFAULT_EDITOR_URL }: { publicReadOnly?: boolean; editorUrl?: string } = {}) {
  const [baseline, setBaseline] = useState<Baseline | null>(null);
  const [state, setState] = useState<AppState>(emptyState);
  const [tab, setTab] = useState<Tab>('overview');
  const [loading, setLoading] = useState(true); const [loadError, setLoadError] = useState('');
  const [online, setOnline] = useState(true); const [pending, setPending] = useState<Pending[]>([]);
  const [syncing, setSyncing] = useState(false); const [cached, setCached] = useState(false); const [shellCached, setShellCached] = useState(false);
  const [toast, setToast] = useState(''); const [mobileNav, setMobileNav] = useState(false);
  const [newRoundOpen, setNewRoundOpen] = useState(false); const [queueOpen, setQueueOpen] = useState(false);
  const [recordId, setRecordId] = useState<string | null>(null); const [measureId, setMeasureId] = useState<string | null>(null);
  const [selectedRoundId, setSelectedRoundId] = useState(''); const [selectedPlotId, setSelectedPlotId] = useState('');
  const [plotModal, setPlotModal] = useState<BaselinePlot | null>(null);
  const [provinceFilter, setProvinceFilter] = useState(''); const [stratumFilter, setStratumFilter] = useState('');
  const [search, setSearch] = useState(''); const [recordPage, setRecordPage] = useState(0); const [speciesFilter, setSpeciesFilter] = useState('');
  const syncRef = useRef(false); const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const notify = useCallback((message: string) => { setToast(message); if (toastTimer.current) clearTimeout(toastTimer.current); toastTimer.current = setTimeout(() => setToast(''), 6000); }, []);
  const refreshPending = useCallback(async () => { if (publicReadOnly) return []; const p = await listPending(); setPending(p); return p; }, [publicReadOnly]);
  const refreshState = useCallback(async () => { if (publicReadOnly) return emptyState; const s = await api<AppState>('/api/state'); setState(s); await writeCachedState(s).catch(() => {}); return s; }, [publicReadOnly]);
  const go = useCallback((next: Tab) => { setTab(next); setMobileNav(false); setSearch(''); setRecordPage(0); if (typeof window !== 'undefined') { window.history.replaceState(null, '', '#' + next); window.scrollTo({ top: 0, behavior: 'smooth' }); } }, []);

  useEffect(() => {
    let alive = true;
    const hash = location.hash.slice(1) as Tab; if (nav.some(n => n.id === hash)) setTab(hash);
    if (publicReadOnly) {
      const controller = new AbortController();
      setState(emptyState); setPending([]);
      fetch('./baseline.json', { signal: controller.signal })
        .then(async response => { if (!response.ok) throw new Error('โหลดข้อมูลเบสไลน์ไม่สำเร็จ กรุณาลองใหม่'); return await response.json() as Baseline; })
        .then(data => { if (alive) { setBaseline(data); setLoadError(''); } })
        .catch(error => { if (alive) setLoadError(errorMessage(error)); })
        .finally(() => { if (alive) setLoading(false); });
      return () => { alive = false; controller.abort(); };
    }
    setOnline(navigator.onLine);
    const onOnline = () => setOnline(true); const onOffline = () => setOnline(false);
    addEventListener('online', onOnline); addEventListener('offline', onOffline);
    (async () => {
      try {
        const [b, s] = await Promise.all([api<Baseline>('/api/baseline'), api<AppState>('/api/state')]);
        if (!alive) return; setBaseline(b); setState(s);
        await Promise.all([writeCachedBaseline(b), writeCachedState(s)]); setCached(true);
      } catch (e) {
        try { const [b, s] = await Promise.all([readCachedBaseline(), readCachedState()]); if (!alive) return; if (b) { setBaseline(b); setState(s || emptyState); setCached(true); setLoadError('กำลังใช้ข้อมูลที่บันทึกไว้ในเครื่อง'); } else setLoadError(errorMessage(e)); } catch { setLoadError(errorMessage(e)); }
      } finally { if (alive) { setLoading(false); refreshPending().catch(() => {}); } }
    })();
    if ('serviceWorker' in navigator) navigator.serviceWorker.register('/sw.js').catch(() => {});
    const onWorkerMessage = (e: MessageEvent) => { if (e.data?.type === 'SHELL_CACHED') { setShellCached(Boolean(e.data.ok)); notify(e.data.ok ? 'ดาวน์โหลดข้อมูลและหน้าแอปไว้ในเครื่องแล้ว' : 'เก็บข้อมูลแล้ว แต่ดาวน์โหลดหน้าแอปยังไม่ครบ กรุณาเตรียมลงพื้นที่อีกครั้งเมื่อสัญญาณพร้อม'); } };
    navigator.serviceWorker?.addEventListener('message', onWorkerMessage);
    return () => { alive = false; removeEventListener('online', onOnline); removeEventListener('offline', onOffline); navigator.serviceWorker?.removeEventListener('message', onWorkerMessage); };
  }, [publicReadOnly, refreshPending, notify]);

  const syncPending = useCallback(async () => {
    if (publicReadOnly || syncRef.current || !navigator.onLine) return; syncRef.current = true; setSyncing(true);
    let sent = 0; const blocked = new Set<string>();
    try {
      const list = await listPending();
      for (const p of list.sort((a, b) => (a.kind === 'observation' ? 0 : 1) - (b.kind === 'observation' ? 0 : 1))) {
        const target = p.kind === 'observation' ? `${p.payload.roundId}:${p.payload.recordId}` : `${p.roundId}:${p.recordId}`;
        if (blocked.has(target)) continue;
        try {
          if (p.kind === 'observation') await api('/api/observations', { method: 'POST', body: JSON.stringify(p.payload) });
          else { const form = new FormData(); form.append('roundId', p.roundId); form.append('recordId', p.recordId); form.append('file', p.file, p.fileName); form.append('operationId', p.key.replace(/^pending:/, '')); await api('/api/evidence', { method: 'POST', body: form }); }
          await removePending(p.key); sent++;
        } catch (e) { await markPendingError(p, errorMessage(e)); blocked.add(target); if (!(e as { status?: number }).status) break; }
      }
      await refreshPending(); await refreshState(); setLoadError('');
      if (sent) notify(`ส่งถึงส่วนกลางแล้ว ${sent} รายการ`); else if (list.length) notify('มีรายการที่ต้องตรวจสอบก่อนส่ง ดูที่รายการรอส่ง');
    } catch (e) { notify(errorMessage(e)); } finally { syncRef.current = false; setSyncing(false); }
  }, [publicReadOnly, notify, refreshPending, refreshState]);
  useEffect(() => { if (!publicReadOnly && online && !loading && pending.length && !pending.some(p => p.error)) syncPending(); }, [publicReadOnly, online, loading, pending.length, syncPending]);

  async function cacheForField() {
    if (publicReadOnly || !baseline) return;
    try {
      await Promise.all([writeCachedBaseline(baseline), writeCachedState(state)]); setCached(true);
      if ('serviceWorker' in navigator) {
        const registration = await Promise.race([navigator.serviceWorker.ready, new Promise<never>((_, reject) => setTimeout(() => reject(new Error('ไม่สามารถเตรียมหน้าแอปได้')), 12000))]);
        const urls = performance.getEntriesByType('resource').map(e => e.name).filter(url => url.startsWith(location.origin));
        registration.active?.postMessage({ type: 'CACHE_SHELL', urls });
        notify('เก็บข้อมูลแล้ว กำลังเตรียมหน้าแอปสำหรับเปิดแบบออฟไลน์…');
      } else notify('บันทึกข้อมูลลงเครื่องแล้ว เบราว์เซอร์นี้ไม่รองรับการเปิดแอปแบบออฟไลน์');
    } catch { notify('บันทึกลงเครื่องไม่สำเร็จ โปรดตรวจพื้นที่ว่างและการอนุญาตของเบราว์เซอร์'); }
  }

  const recordMap = useMemo(() => new Map((baseline?.records || []).map(r => [r.id, r])), [baseline]);
  const plotMap = useMemo(() => new Map((baseline?.plots || []).map(p => [p.id, p])), [baseline]);
  const provinces = useMemo(() => [...new Set((baseline?.plots || []).map(p => p.province))], [baseline]);
  const strata = useMemo(() => [...new Set((baseline?.plots || []).map(p => p.stratum))], [baseline]);
  const speciesNames = useMemo(() => [...new Set((baseline?.records || []).map(r => r.species))].sort(), [baseline]);
  const selectedRound = state.rounds.find(r => r.id === selectedRoundId) || state.rounds[0];
  const filteredPlots = useMemo(() => (baseline?.plots || []).filter(p => (!provinceFilter || p.province === provinceFilter) && (!stratumFilter || p.stratum === stratumFilter) && (!search || `${p.name} ${p.sourcePlotCode} ${p.province}`.toLowerCase().includes(search.toLowerCase()))), [baseline, provinceFilter, stratumFilter, search]);
  const filteredRecords = useMemo(() => (baseline?.records || []).filter(r => (!selectedPlotId || r.plotId === selectedPlotId) && (!speciesFilter || r.species === speciesFilter) && (!search || `${r.tag} ${r.species} ${r.plotId} ${r.id}`.toLowerCase().includes(search.toLowerCase()))), [baseline, selectedPlotId, search, speciesFilter]);
  const activeRecord = recordId ? recordMap.get(recordId) : null;
  const measureRecord = measureId ? recordMap.get(measureId) : null;
  const pendingTargets = new Set(pending.filter((p): p is PendingObservation => p.kind === 'observation').map(p => p.payload.recordId));
  const currentObservation = selectedRound && measureId ? state.observations.find(o => o.roundId === selectedRound.id && o.recordId === measureId) : undefined;
  const pendingObservation = selectedRound && measureId ? pending.find((p): p is PendingObservation => p.kind === 'observation' && p.payload.roundId === selectedRound.id && p.payload.recordId === measureId) : undefined;
  const sourceFlagged = baseline?.records.filter(r => r.flags.length).length || 0;

  async function saveMeasurement(input: ObservationInput, photos: File[], next: boolean) {
    if (publicReadOnly) return;
    await queueObservation(input); for (const photo of photos) await queuePhoto(input.roundId, input.recordId, photo);
    await refreshPending(); notify('บันทึกในเครื่องแล้ว • รอส่งถึงส่วนกลาง');
    if (navigator.onLine) await syncPending();
    if (next && baseline && selectedRound) {
      const list = baseline.records.filter(r => r.plotId === recordMap.get(input.recordId)?.plotId && selectedRound.plotIds.includes(r.plotId));
      const i = list.findIndex(r => r.id === input.recordId); if (i + 1 < list.length) setMeasureId(list[i + 1].id); else { setMeasureId(null); notify('ถึงรายการสุดท้ายของแปลงแล้ว'); }
    } else setMeasureId(null);
  }
  function startMeasurement(record: BaselineRecord) {
    if (publicReadOnly) return;
    const round = state.rounds.find(r => r.id === selectedRoundId && r.status === 'open' && r.plotIds.includes(record.plotId)) || state.rounds.find(r => r.status === 'open' && r.plotIds.includes(record.plotId));
    if (!round) { notify('สร้างรอบสำรวจที่มีแปลงนี้ก่อนบันทึกผลวัด'); setNewRoundOpen(true); return; }
    setSelectedRoundId(round.id); setRecordId(null); setMeasureId(record.id);
  }

  if (loading) return <div className="loading-screen"><div className="brand-mark"><Trees size={32} /></div><h1>Mangrove <span>MRV</span></h1><p>{publicReadOnly ? 'กำลังเปิดข้อมูลเบสไลน์สาธารณะ' : 'กำลังเปิดข้อมูลเบสไลน์และรอบสำรวจ'}</p><Loader2 className="spin" size={22} /></div>;
  if (!baseline) return <div className="loading-screen"><TriangleAlert size={38} /><h1>ยังเปิดข้อมูลไม่ได้</h1><p>{loadError}</p><button className="button primary" onClick={() => location.reload()}><RefreshCw size={17} />ลองอีกครั้ง</button></div>;

  const sampleStock = baseline.plots.reduce((sum, p) => sum + (p.sourceStockTco2e || 0), 0);
  const provinceSummary = provinces.map(province => { const plots = baseline.plots.filter(p => p.province === province); return { province, plots: plots.length, stock: plots.reduce((sum, p) => sum + p.sourceStockTco2e, 0), records: plots.reduce((sum, p) => sum + p.recordCount, 0) }; }).sort((a, b) => b.stock - a.stock);
  const maxProvinceStock = Math.max(...provinceSummary.map(p => p.stock), 1);
  const currentNav = nav.find(n => n.id === tab)!;

  return <div className={`app-shell${publicReadOnly ? ' public-viewer' : ''}`}>
    {mobileNav && <div className="nav-scrim" onClick={() => setMobileNav(false)} />}
    <aside className={`sidebar ${mobileNav ? 'open' : ''}`}>
      <a className="brand" href="#overview" onClick={e => { e.preventDefault(); go('overview'); }}><span className="brand-mark"><Trees size={27} /></span><span>Mangrove <b>MRV</b><small>FOREST MONITORING</small></span></a>
      <div className="project-switch"><span className="project-icon"><Sprout size={18} /></span><div><strong>MOC2 · VSD</strong><small>โครงการป่าชายเลน</small></div><ChevronDown size={15} /></div>
      <div className="nav-label">{publicReadOnly ? 'PUBLIC BASELINE' : 'WORKSPACE'}</div>
      <nav aria-label="เมนูหลัก">{nav.map(n => <button key={n.id} className={`nav-item ${tab === n.id ? 'active' : ''}`} onClick={() => go(n.id)}><n.icon size={19} /><span>{n.label}</span>{n.id === 'rounds' && state.rounds.length > 0 && <em>{state.rounds.length}</em>}{n.id === 'quality' && <span className="nav-dot" />}</button>)}</nav>
      <div className="sidebar-guide"><div className="guide-icon"><Leaf size={21} /></div><strong>ทุกการวัด มีที่มา</strong><p>เชื่อมข้อมูลภาคสนามกับเบสไลน์ เพื่อการติดตามที่ตรวจสอบได้</p><button onClick={() => go('reports')}>ดูรายงานและแหล่งข้อมูล <ArrowUpRight size={14} /></button></div>
      <div className="sidebar-bottom"><span className="private-icon">{publicReadOnly ? <FileSpreadsheet size={16} /> : <LockKeyhole size={16} />}</span><div><strong>{publicReadOnly ? 'เว็บไซต์สาธารณะ' : 'พื้นที่ทำงานส่วนตัว'}</strong><small>{publicReadOnly ? 'อ่านและดาวน์โหลดข้อมูลเบสไลน์' : 'เข้าถึงผ่านบัญชี ChatGPT'}</small></div></div>
    </aside>
    <div className="workspace">
      <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-menu" aria-label="เปิดเมนู" onClick={() => setMobileNav(true)}><Menu size={22} /></button><span className="breadcrumb-project">MOC2 · VSD</span><ChevronRight size={14} /><strong>{currentNav.label}</strong></div><div className="topbar-actions">{publicReadOnly ? <><span className="public-label"><FileSpreadsheet size={15} />ข้อมูลเบสไลน์สาธารณะ</span><a className="public-source-link" href="https://github.com/saratchai1/mrv-002" target="_blank" rel="noreferrer">GitHub <ExternalLink size={13} /></a></> : <><span className={`connection ${online ? '' : 'offline'}`}>{online ? <Cloud size={15} /> : <WifiOff size={15} />}{online ? 'เชื่อมต่อแล้ว' : 'ออฟไลน์'}</span><button className={`sync-counter ${pending.length ? 'has-pending' : ''}`} onClick={() => setQueueOpen(true)} title="รายการรอส่ง">{pending.length ? <Upload size={15} /> : <CheckCheck size={15} />}{pending.length ? `${pending.length} รอส่ง` : 'ไม่มีรายการค้าง'}</button><div className="avatar">MR</div></>}</div></header>
      <main className="main-content">
        {loadError && <Banner kind="warn">{loadError} {online && !publicReadOnly && <button className="text-link" onClick={() => refreshState().then(() => setLoadError('')).catch(e => notify(errorMessage(e)))}>โหลดข้อมูลล่าสุด</button>}</Banner>}
        <div className="page-heading"><div><div className="eyebrow">{currentNav.en.toUpperCase()} <span className="eyebrow-dot" /> MOC2 / VSD</div><h1>{tab === 'overview' ? 'ภาพรวมเบสไลน์' : currentNav.label}</h1><p>{tab === 'overview' ? 'เริ่มต้นจากข้อมูลจริง ติดตามการเปลี่ยนแปลงได้ทุกรอบสำรวจ' : tab === 'plots' ? 'ขอบเขตแปลงตัวอย่าง ชนิดป่า และคาร์บอนจากไฟล์ต้นทาง' : tab === 'trees' ? 'ค้นหารายการต้นทาง แล้วเชื่อมกับการวัดซ้ำในภาคสนาม' : tab === 'rounds' ? publicReadOnly ? 'เปิดพื้นที่สำรวจเพื่อบันทึกผลวัดและจัดการรอบสำรวจ' : 'จัดการงานสำรวจ บันทึกผลวัด และติดตามความครบถ้วน' : tab === 'quality' ? 'ข้อมูลที่ต้องยืนยัน ก่อนนำไปเปรียบเทียบและจัดทำรายงาน' : publicReadOnly ? 'ข้อมูลเบสไลน์พร้อมแหล่งอ้างอิง สำหรับประกอบการติดตาม MRV' : 'ผลสำรวจพร้อมแหล่งอ้างอิง สำหรับประกอบการติดตาม MRV'}</p></div><div className="heading-actions">{publicReadOnly ? <EditorLink editorUrl={editorUrl} /> : <>{tab !== 'rounds' && <button className="button secondary" onClick={cacheForField}><ArrowDownToLine size={16} /><span>{cached && shellCached ? 'พร้อมใช้ออฟไลน์' : 'เตรียมลงพื้นที่'}</span></button>}<button className="button primary" onClick={() => setNewRoundOpen(true)}><Plus size={18} />สร้างรอบสำรวจ</button></>}</div></div>

        {tab === 'overview' && <>
          <div className="overview-hero"><div className="hero-copy"><span className="hero-kicker"><span /> BASELINE · ปีอ้างอิง {baseline.meta.baselineYearBE || 'ไม่ระบุ'}</span><h2>รู้จุดเริ่มต้น<br />เห็นการเติบโตอย่างต่อเนื่อง</h2><p>ทะเบียนข้อมูล {number(baseline.meta.measurementCount)} รายการ จาก {baseline.meta.samplePlotCount} แปลงตัวอย่าง<br className="desktop-only" />พร้อมสำหรับการกลับไปวัด ติดตาม และตรวจสอบ</p><button onClick={() => { go('trees'); setSelectedPlotId(''); }} className="hero-link">สำรวจข้อมูลเบสไลน์ <ArrowRight size={17} /></button></div><div className="hero-visual" aria-hidden="true"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="hero-tree"><Trees size={125} strokeWidth={1.1} /></div><span className="floating-label label-one"><MapPin size={15} />{provinces.length} จังหวัด</span><span className="floating-label label-two"><Leaf size={15} />{number(baseline.meta.sampleAreaRai, 1)} ไร่ตัวอย่าง</span><span className="hero-grid" /></div><div className="hero-bottom"><FileSpreadsheet size={15} /><span>{baseline.meta.fileName}</span><span className="hero-source">ข้อมูลจากไฟล์ต้นฉบับ</span></div></div>
          <div className="kpi-grid"><Kpi label="แปลงตัวอย่าง" value={number(baseline.meta.samplePlotCount)} unit="แปลง" detail={`${number(baseline.meta.sampleAreaRai, 1)} ไร่ · ${provinces.length} จังหวัด`} icon={MapPin} /><Kpi label="รายการวัดในเบสไลน์" value={number(baseline.meta.measurementCount)} unit="รายการ" detail={`${number(baseline.meta.sourceTreeCount)} ต้น ตามเครื่องหมายนับในไฟล์`} icon={Trees} /><Kpi label="คาร์บอนรวมในแปลงตัวอย่าง" value={number(sampleStock, 2)} unit="tCO₂e" detail="ผลคำนวณต้นทาง · ยังไม่ใช่เครดิตรับรอง" icon={Leaf} />{publicReadOnly ? <Kpi label="ชนิดไม้ที่พบในแปลงตัวอย่าง" value={number(speciesNames.length)} unit="ชนิด" detail="ชนิดไม้ตามรายการวัดในไฟล์ต้นฉบับ" icon={Sprout} tone="gold" /> : <Kpi label="รอบสำรวจที่บันทึก" value={number(state.rounds.length)} unit="รอบ" detail={`${number(state.observations.length)} รายการวัดซ้ำที่ส่งถึงส่วนกลาง`} icon={ClipboardCheck} tone="gold" />}</div>
          <div className="dashboard-grid"><section className="panel province-panel"><SectionHead eyebrow="BASELINE DISTRIBUTION" title="คาร์บอนแปลงตัวอย่าง แยกจังหวัด" action={<span className="unit-chip">tCO₂e</span>} /><div className="province-chart">{provinceSummary.map((p, i) => <button className="province-row" key={p.province} onClick={() => { setProvinceFilter(p.province); go('plots'); }}><div className="province-label"><span>{p.province}</span><small>{p.plots} แปลง</small></div><div className="bar-track"><span style={{ width: `${p.stock / maxProvinceStock * 100}%`, opacity: 1 - i * .055 }} /></div><strong>{number(p.stock, 2)}</strong></button>)}</div><div className="panel-footnote">รวมเฉพาะพื้นที่แปลงตัวอย่าง ไม่ใช่ยอดรวมทั้งโครงการ</div></section>
          <section className="panel readiness-panel"><SectionHead eyebrow="NEXT STEPS" title="เตรียมพร้อมสำหรับรอบถัดไป" /><div className="step-item"><div className="step-icon done"><Check size={17} /></div><div><strong>นำเข้าข้อมูลเบสไลน์</strong><p>{number(baseline.meta.sheetCount)} ชีต · เก็บเลขแถวและแหล่งที่มา</p></div><span className="badge green">พร้อม</span></div><div className="step-item"><div className="step-icon warn"><TriangleAlert size={17} /></div><div><strong>ยืนยันป้ายและลำต้น</strong><p>รายการวัดอาจรวมหลายลำต้นและป้ายซ้ำ</p></div></div><div className="step-item"><div className="step-icon"><ClipboardList size={17} /></div><div><strong>เปิดรอบสำรวจใหม่</strong><p>เลือกแปลงและวันที่ลงพื้นที่จริง</p></div></div><button className="button secondary full" onClick={() => go('quality')}>ดูสิ่งที่ต้องตรวจสอบ <ArrowRight size={16} /></button><div className="readiness-note"><Info size={16} /><p>วันที่วัดและจุดวัดเดิมยังต้องยืนยันจากเอกสารหรือภาคสนาม</p></div></section></div>
          <section className="panel"><SectionHead eyebrow="SAMPLE PLOT REGISTER" title={publicReadOnly ? "ทะเบียนแปลงตัวอย่าง" : "แปลงตัวอย่างของคุณ"} action={<button className="text-link" onClick={() => { setProvinceFilter(''); go('plots'); }}>ดูทั้งหมด {baseline.plots.length} แปลง <ArrowRight size={15} /></button>} /><PlotTable plots={baseline.plots.slice(0, 5)} onOpen={setPlotModal} /><div className="panel-footnote"><span className="dot green-dot" /> เบสไลน์ต้นทาง · ขนาดแปลง 0.5–1 ไร่ตามไฟล์</div></section>
          <div className="context-strip"><div><span className="context-icon"><BarChart3 size={20} /></span><div><strong>ประมาณการระดับโครงการจาก Excel</strong><p>{number(baseline.meta.projectAreaRai, 2)} ไร่ · {baseline.meta.projectPlotCount} แปลงโครงการ</p></div></div><div className="context-value">{number(baseline.meta.projectBaselineTco2e, 2)} <small>tCO₂e</small><span>ยอดเบสไลน์ที่ขยายผลตามชั้นภูมิในไฟล์</span></div><button className="text-link" onClick={() => go('reports')}>ดูขอบเขตรายงาน <ArrowUpRight size={16} /></button></div>
        </>}

        {tab === 'plots' && <>
          <div className="filter-toolbar"><div className="search-field"><Search size={17} /><input placeholder="ค้นหารหัสแปลง หรือจังหวัด…" value={search} onChange={e => setSearch(e.target.value)} /></div><select aria-label="กรองจังหวัด" value={provinceFilter} onChange={e => setProvinceFilter(e.target.value)}><option value="">ทุกจังหวัด</option>{provinces.map(p => <option key={p}>{p}</option>)}</select><select aria-label="กรองชั้นภูมิ" value={stratumFilter} onChange={e => setStratumFilter(e.target.value)}><option value="">ทุกชั้นภูมิ</option>{strata.map(s => <option key={s}>{s}</option>)}</select><span className="toolbar-count">{filteredPlots.length} แปลง</span></div>
          <div className="mini-stat-row"><span><MapPin size={17} /> พื้นที่ตัวอย่าง <b>{number(filteredPlots.reduce((sum, p) => sum + p.areaRai, 0), 1)} ไร่</b></span><span><Trees size={17} /> รายการวัด <b>{number(filteredPlots.reduce((sum, p) => sum + p.recordCount, 0))}</b></span><span><Leaf size={17} /> คาร์บอนต้นทาง <b>{number(filteredPlots.reduce((sum, p) => sum + p.sourceStockTco2e, 0), 2)} tCO₂e</b></span></div>
          <section className="panel no-padding"><PlotTable plots={filteredPlots} onOpen={setPlotModal} /></section><Banner>พิกัดมุมแปลงในไฟล์เป็น Easting / Northing และยังไม่ยืนยันระบบพิกัด จึงแสดงตารางพิกัดต้นทางในรายละเอียดแปลง</Banner>
        </>}

        {tab === 'trees' && <>
          <Banner>หนึ่งรายการในตารางคือหนึ่งแถวการวัดต้นทาง ป้ายซ้ำหรือหลายลำต้นต้องยืนยันตัวตนก่อนจับคู่การวัดซ้ำ</Banner>
          <div className="filter-toolbar"><div className="search-field"><Search size={17} /><input placeholder="ค้นหาป้ายต้นไม้ ชนิดไม้ หรือรหัสรายการ…" value={search} onChange={e => { setSearch(e.target.value); setRecordPage(0); }} /></div><select aria-label="เลือกแปลง" value={selectedPlotId} onChange={e => { setSelectedPlotId(e.target.value); setRecordPage(0); }}><option value="">ทุกแปลง</option>{baseline.plots.map(p => <option value={p.id} key={p.id}>{p.id} · {p.province}</option>)}</select><select aria-label="เลือกชนิดไม้" value={speciesFilter} onChange={e => { setSpeciesFilter(e.target.value); setRecordPage(0); }}><option value="">ทุกชนิดไม้</option>{speciesNames.map(s => <option key={s}>{s}</option>)}</select><CsvButton publicReadOnly={publicReadOnly} /></div>
          <section className="panel no-padding"><div className="table-caption"><strong>ทะเบียนรายการวัด</strong><span>{number(filteredRecords.length)} รายการ</span></div><div className="table-scroll"><table className="data-table record-table"><thead><tr><th>หมายเลขป้าย / แหล่งที่มา</th><th>แปลงตัวอย่าง</th><th>ชนิดไม้</th><th className="numeric">DBH (ซม.)</th><th className="numeric">คาร์บอน (tCO₂e)</th><th>ข้อมูลต้นทาง</th><th /></tr></thead><tbody>{filteredRecords.slice(recordPage * 50, recordPage * 50 + 50).map(r => <tr key={r.id} onClick={() => setRecordId(r.id)} tabIndex={0} onKeyDown={e => { if (e.key === 'Enter') setRecordId(r.id); }}><td><div className="cell-main"><span className="tree-symbol"><TreePine size={17} /></span><div><strong>{r.tag || 'ไม่ระบุป้าย'}</strong><small>{r.plotId} · แถว {r.row}</small></div></div></td><td><span className="code-chip">{r.plotId}</span></td><td>{r.species}</td><td className="numeric">{number(r.dbhCm, 2)}</td><td className="numeric">{number(r.stockTco2e, 4)}</td><td>{r.flags.length ? <span className="badge amber"><TriangleAlert size={12} />ตรวจสอบ {r.flags.length}</span> : <span className="badge neutral">มีข้อมูลวัด</span>}{pendingTargets.has(r.id) && <span className="pending-dot" title="มีรายการรอส่ง" />}</td><td><ChevronRight size={16} /></td></tr>)}</tbody></table></div>{!filteredRecords.length && <Empty icon={Search} title="ไม่พบรายการ">ลองเปลี่ยนคำค้นหรือเลือกแปลงอื่น</Empty>}<div className="pagination"><span>แสดง {filteredRecords.length ? number(recordPage * 50 + 1) : 0}–{number(Math.min(recordPage * 50 + 50, filteredRecords.length))} จาก {number(filteredRecords.length)} รายการ</span><div><button className="icon-button" disabled={recordPage === 0} onClick={() => setRecordPage(p => p - 1)} aria-label="หน้าก่อน"><ChevronLeft size={18} /></button><span>{recordPage + 1} / {Math.max(1, Math.ceil(filteredRecords.length / 50))}</span><button className="icon-button" disabled={(recordPage + 1) * 50 >= filteredRecords.length} onClick={() => setRecordPage(p => p + 1)} aria-label="หน้าถัดไป"><ChevronRight size={18} /></button></div></div></section>
        </>}

        {tab === 'rounds' && publicReadOnly && <PublicSurveyView editorUrl={editorUrl} samplePlotCount={baseline.meta.samplePlotCount} measurementCount={baseline.meta.measurementCount} />}
        {tab === 'rounds' && !publicReadOnly && <>
          <div className="field-prep"><div className="field-prep-icon"><Cloud size={26} /></div><div><h3>เตรียมข้อมูลก่อนออกพื้นที่</h3><p>ดาวน์โหลดทะเบียนและหน้าแอปไว้ในเครื่อง บันทึกผลวัดได้แม้ไม่มีสัญญาณ แล้วส่งเมื่อออนไลน์</p></div><button className="button secondary" onClick={cacheForField}><Download size={16} />{shellCached ? 'ดาวน์โหลดอีกครั้ง' : 'ดาวน์โหลดลงเครื่อง'}</button></div>
          {!state.rounds.length ? <section className="panel"><Empty title="เริ่มการสำรวจรอบแรก" action={<button className="button primary" onClick={() => setNewRoundOpen(true)}><Plus size={17} />สร้างรอบสำรวจ</button>}>เลือกแปลงตัวอย่างที่จะกลับไปวัด แล้วเชื่อมผลใหม่กับรายการเบสไลน์เดิม</Empty></section> : <div className="rounds-layout"><div className="round-list">{state.rounds.map(round => { const observations = state.observations.filter(o => o.roundId === round.id); const expected = baseline.records.filter(r => round.plotIds.includes(r.plotId)).length; return <button key={round.id} className={`round-card ${selectedRound?.id === round.id ? 'selected' : ''}`} onClick={() => { setSelectedRoundId(round.id); setSelectedPlotId(round.plotIds[0]); setSearch(''); }}><div className="round-card-top"><span className={`round-icon ${round.status === 'locked' ? 'locked' : ''}`}>{round.status === 'locked' ? <LockKeyhole size={19} /> : <ClipboardList size={19} />}</span><span className={`badge ${round.status === 'locked' ? 'green' : 'blue'}`}>{round.status === 'locked' ? 'ล็อกแล้ว' : 'กำลังสำรวจ'}</span></div><h3>{round.name}</h3><p><CalendarDays size={14} />{dateLabel(round.date)} · {round.plotIds.length} แปลง</p><div className="progress-line"><span style={{ width: `${expected ? observations.length / expected * 100 : 0}%` }} /></div><div className="round-progress"><span>{number(observations.length)} / {number(expected)} รายการ</span><b>{number(expected ? observations.length / expected * 100 : 0, 0)}%</b></div></button>; })}</div>{selectedRound && <section className="panel round-detail"><SectionHead title={selectedRound.name} action={<button className="text-link" onClick={() => go('reports')}>รายงาน <ArrowUpRight size={15} /></button>} /><div className="round-detail-meta"><span><CalendarDays size={15} />{dateLabel(selectedRound.date)}</span><span>{selectedRound.plotIds.length} แปลงตัวอย่าง</span>{selectedRound.status === 'locked' && <span className="badge green"><LockKeyhole size={12} />อ่านอย่างเดียว</span>}</div>{selectedRound.notes && <p className="round-notes">{selectedRound.notes}</p>}<div className="filter-toolbar compact"><select aria-label="เลือกแปลงในรอบ" value={selectedRound.plotIds.includes(selectedPlotId) ? selectedPlotId : ''} onChange={e => setSelectedPlotId(e.target.value)}><option value="">ทุกแปลงในรอบนี้</option>{selectedRound.plotIds.map(id => <option key={id}>{id}</option>)}</select><div className="search-field"><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="ค้นหาป้าย หรือชนิดไม้…" /></div></div><div className="field-record-list">{baseline.records.filter(r => selectedRound.plotIds.includes(r.plotId) && (!selectedRound.plotIds.includes(selectedPlotId) || r.plotId === selectedPlotId) && (!search || `${r.tag} ${r.species} ${r.id}`.toLowerCase().includes(search.toLowerCase()))).slice(0, 100).map(r => { const observation = state.observations.find(o => o.roundId === selectedRound.id && o.recordId === r.id); const isPending = pending.some(p => p.kind === 'observation' && p.payload.roundId === selectedRound.id && p.payload.recordId === r.id); return <button className="field-record" key={r.id} onClick={() => selectedRound.status === 'locked' ? setRecordId(r.id) : setMeasureId(r.id)}><span className={`record-state-icon ${observation ? 'done' : ''}`}>{observation ? <Check size={17} /> : <TreePine size={17} />}</span><div><strong>{r.tag || 'ไม่มีป้าย'} <span>· {r.species}</span></strong><small>{r.plotId} แถว {r.row} · เบสไลน์ {number(r.dbhCm, 2)} ซม.</small></div><span className={`badge ${isPending ? 'amber' : observation ? 'green' : 'neutral'}`}>{isPending ? 'รอส่ง' : observation ? statusText[observation.status] : 'ยังไม่ได้สำรวจ'}</span><ChevronRight size={16} /></button>; })}</div><div className="panel-footnote">แสดง 100 รายการแรกของตัวกรอง · ค้นหาหมายเลขป้ายเพื่อเปิดรายการที่ต้องการ</div></section>}</div>}
        </>}

        {tab === 'quality' && <QualityView baseline={baseline} onRecord={setRecordId} onPlot={id => { setSelectedPlotId(id); go('trees'); }} />}
        {tab === 'reports' && <ReportsView publicReadOnly={publicReadOnly} baseline={baseline} state={state} selectedRoundId={selectedRoundId} onSelectRound={setSelectedRoundId} pending={pending} refreshState={refreshState} notify={notify} />}
        <footer className="workspace-footer"><span><Leaf size={13} /> Mangrove MRV</span><span>{publicReadOnly ? "ข้อมูลเบสไลน์ต้นทาง · เผยแพร่เพื่อการตรวจสอบ" : "ข้อมูลต้นทาง + ผลสำรวจที่ตรวจสอบย้อนกลับได้"}</span><span>{baseline.meta.samplePlotCount} แปลง · {number(baseline.meta.measurementCount)} รายการ</span></footer>
      </main>
    </div>
    {toast && <div role="status" className="toast"><Info size={18} /><span>{toast}</span><button aria-label="ปิดข้อความ" onClick={() => setToast('')}><X size={16} /></button></div>}
    {!publicReadOnly && newRoundOpen && <NewRoundModal baseline={baseline} onClose={() => setNewRoundOpen(false)} onSave={async payload => { const result = await api<{ round: Round }>('/api/rounds', { method: 'POST', body: JSON.stringify(payload) }); await refreshState(); setSelectedRoundId(result.round.id); setSelectedPlotId(result.round.plotIds[0]); setNewRoundOpen(false); go('rounds'); notify('สร้างรอบสำรวจและบันทึกถึงส่วนกลางแล้ว'); }} />}
    {plotModal && <Modal title={`แปลงตัวอย่าง ${plotModal.id}`} subtitle={`${plotModal.province} · ${plotModal.coast} · ชั้นภูมิ${plotModal.stratum}`} onClose={() => setPlotModal(null)} wide><div className="modal-body"><div className="detail-metrics"><div><span>พื้นที่แปลง</span><strong>{number(plotModal.areaRai, 1)} <small>ไร่</small></strong></div><div><span>รายการวัด</span><strong>{number(plotModal.recordCount)}</strong></div><div><span>ต้นตามเครื่องหมายนับ</span><strong>{number(plotModal.sourceTreeCount)}</strong></div><div><span>คาร์บอนต้นทาง</span><strong>{number(plotModal.sourceStockTco2e, 2)} <small>tCO₂e</small></strong></div></div><div className="detail-grid"><div><h3>ข้อมูลแปลง</h3><dl className="definition-list"><dt>รหัสในชีตต้นทาง</dt><dd>{plotModal.sourcePlotCode}</dd><dt>ค่าเฉลี่ย DBH</dt><dd>{number(plotModal.meanDbhCm, 2)} ซม.</dd><dt>คาร์บอนต่อไร่</dt><dd>{number(plotModal.stockPerRai, 2)} tCO₂e/ไร่</dd><dt>หมายเลขป้ายไม่ซ้ำ</dt><dd>{number(plotModal.uniqueTagCount)}</dd><dt>แหล่งข้อมูล</dt><dd>ชีต {plotModal.id}</dd></dl></div><div><h3>พิกัดมุมแปลงจากไฟล์</h3>{plotModal.corners?.length ? <table className="mini-table"><thead><tr><th>จุด</th><th>Easting</th><th>Northing</th></tr></thead><tbody>{plotModal.corners.map((c, i) => <tr key={i}><td>{c.marker}</td><td>{number(c.easting, 0)}</td><td>{number(c.northing, 0)}</td></tr>)}</tbody></table> : <p className="muted">ไม่มีพิกัดมุมแปลงในข้อมูลที่นำเข้า</p>}<p className="helper">ระบบพิกัด: {plotModal.crs || 'ยังไม่ยืนยัน CRS'}</p></div></div>{plotModal.flags.length > 0 && <Banner kind="warn">{plotModal.flags.map(flagText).join(' · ')}</Banner>}</div><div className="modal-actions"><button className="button secondary" onClick={() => setPlotModal(null)}>ปิด</button><button className="button primary" onClick={() => { setSelectedPlotId(plotModal.id); setPlotModal(null); go('trees'); }}>ดูรายการวัด <ArrowRight size={16} /></button></div></Modal>}
    {activeRecord && <RecordModal publicReadOnly={publicReadOnly} editorUrl={editorUrl} record={activeRecord} baseline={baseline} observations={state.observations.filter(o => o.recordId === activeRecord.id)} rounds={state.rounds} evidence={state.evidence.filter(e => e.recordId === activeRecord.id)} onClose={() => setRecordId(null)} onMeasure={() => startMeasurement(activeRecord)} />}
    {!publicReadOnly && measureRecord && selectedRound && <MeasurementEditor key={`${measureRecord.id}:${selectedRound.id}:${currentObservation?.version || 0}`} record={measureRecord} round={selectedRound} observation={currentObservation} pending={pendingObservation} evidence={state.evidence.filter(e => e.recordId === measureRecord.id && e.roundId === selectedRound.id)} onClose={() => setMeasureId(null)} onSave={saveMeasurement} />}
    {!publicReadOnly && queueOpen && <Modal title="การบันทึกและส่งข้อมูล" subtitle="รายการในเครื่องจะถูกส่งตามลำดับเมื่อเชื่อมต่ออินเทอร์เน็ต" onClose={() => setQueueOpen(false)}><div className="modal-body"><div className="queue-summary"><div><span className={`status-dot ${online ? 'green-dot' : 'orange-dot'}`} />{online ? 'ออนไลน์' : 'ออฟไลน์'}</div><strong>{pending.length} รายการรอส่ง</strong></div>{!pending.length ? <Empty icon={CheckCheck} title="ไม่มีรายการค้างส่ง">ผลวัดที่บันทึกสำเร็จอยู่ที่ส่วนกลางแล้ว</Empty> : <div className="queue-items">{pending.map(p => <div className="queue-item" key={p.key}><span className="queue-icon">{p.kind === 'photo' ? <Camera size={18} /> : <ClipboardCheck size={18} />}</span><div><strong>{p.kind === 'photo' ? p.fileName : recordMap.get(p.payload.recordId)?.tag || p.payload.recordId}</strong><p>{p.kind === 'photo' ? `รูปภาพ · ${p.recordId}` : `${p.payload.recordId} · ${statusText[p.payload.status]}`}</p>{p.error && <div className="field-error">{p.error}</div>}</div>{p.kind === 'observation' && <button className="text-link" onClick={() => { setSelectedRoundId(p.payload.roundId); setMeasureId(p.payload.recordId); setQueueOpen(false); }}>ตรวจรายการ</button>}</div>)}</div>}</div><div className="modal-actions"><button className="button secondary" onClick={() => refreshState().then(() => notify('โหลดข้อมูลล่าสุดแล้ว')).catch(e => notify(errorMessage(e)))}>โหลดข้อมูลล่าสุด</button><button className="button primary" disabled={!online || syncing || !pending.length} onClick={syncPending}>{syncing ? <Loader2 size={16} className="spin" /> : <RefreshCw size={16} />}ส่งข้อมูล</button></div></Modal>}
  </div>;
}

function PlotTable({ plots, onOpen }: { plots: BaselinePlot[]; onOpen: (p: BaselinePlot) => void }) { return <div className="table-scroll"><table className="data-table plot-table"><thead><tr><th>แปลงตัวอย่าง</th><th>จังหวัด / ชายฝั่ง</th><th>ชั้นภูมิ</th><th className="numeric">พื้นที่ (ไร่)</th><th className="numeric">รายการวัด</th><th className="numeric">คาร์บอน (tCO₂e)</th><th /></tr></thead><tbody>{plots.map(p => <tr key={p.id} onClick={() => onOpen(p)} tabIndex={0} onKeyDown={e => { if (e.key === 'Enter') onOpen(p); }}><td><div className="cell-main"><span className="plot-symbol"><MapPin size={17} /></span><div><strong>{p.id}</strong><small>{p.sourcePlotCode}</small></div></div></td><td><strong className="normal-weight">{p.province}</strong><small className="cell-sub">{p.coast}</small></td><td><span className={`stratum-pill ${p.stratum.includes('สูง') || p.stratum.includes('มาก') ? 'dense' : p.stratum.includes('กลาง') ? 'medium' : 'low'}`}><span />{p.stratum}</span></td><td className="numeric">{number(p.areaRai, 1)}</td><td className="numeric">{number(p.recordCount)}</td><td className="numeric carbon-cell">{number(p.sourceStockTco2e, 2)}</td><td><ArrowUpRight size={16} /></td></tr>)}</tbody></table>{!plots.length && <Empty icon={Search} title="ไม่พบแปลง">ลองเปลี่ยนตัวกรองหรือคำค้น</Empty>}</div>; }

function NewRoundModal({ baseline, onClose, onSave }: { baseline: Baseline; onClose: () => void; onSave: (data: { name: string; date: string; plotIds: string[]; notes: string; operationId: string }) => Promise<void> }) {
  const [name, setName] = useState(''); const [date, setDate] = useState(today()); const [ids, setIds] = useState<string[]>([]); const [notes, setNotes] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [filter, setFilter] = useState(''); const op = useRef(createOperationId());
  return <Modal title="สร้างรอบสำรวจ" subtitle="กำหนดงานสำหรับการกลับไปวัดต้นไม้ในแปลงเดิม" onClose={onClose} wide><form onSubmit={async e => { e.preventDefault(); if (!ids.length) { setError('เลือกอย่างน้อย 1 แปลงตัวอย่าง'); return; } setBusy(true); setError(''); try { await onSave({ name: name.trim(), date, plotIds: ids, notes: notes.trim(), operationId: op.current }); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }}><div className="modal-body"><div className="form-two"><label>ชื่อรอบสำรวจ <span>*</span><input required maxLength={120} placeholder="เช่น ติดตามการเติบโต ครั้งที่ 1" value={name} onChange={e => setName(e.target.value)} /></label><label>วันที่เริ่มสำรวจ <span>*</span><input required type="date" value={date} onChange={e => setDate(e.target.value)} /></label></div><div className="plot-picker-head"><label>แปลงตัวอย่าง <span>*</span></label><button type="button" className="text-link" onClick={() => setIds(ids.length === baseline.plots.length ? [] : baseline.plots.map(p => p.id))}>{ids.length === baseline.plots.length ? 'ยกเลิกการเลือกทั้งหมด' : 'เลือกทั้งหมด'}</button></div><div className="search-field"><Search size={16} /><input placeholder="ค้นหาแปลงหรือจังหวัด" value={filter} onChange={e => setFilter(e.target.value)} /></div><div className="plot-picker">{baseline.plots.filter(p => `${p.id} ${p.province}`.includes(filter)).map(p => <label className={`plot-option ${ids.includes(p.id) ? 'checked' : ''}`} key={p.id}><input type="checkbox" checked={ids.includes(p.id)} onChange={() => setIds(current => current.includes(p.id) ? current.filter(id => id !== p.id) : [...current, p.id])} /><span><strong>{p.id}</strong><small>{p.province} · {number(p.recordCount)} รายการ</small></span></label>)}</div><p className="helper">เลือก {ids.length} แปลง · {number(baseline.plots.filter(p => ids.includes(p.id)).reduce((sum, p) => sum + p.recordCount, 0))} รายการวัด</p><label className="form-label">หมายเหตุ / แผนงาน<textarea rows={2} maxLength={2000} placeholder="ทีมสำรวจ วัตถุประสงค์ หรือสิ่งที่ต้องตรวจเป็นพิเศษ" value={notes} onChange={e => setNotes(e.target.value)} /></label>{error && <Banner kind="warn">{error}</Banner>}</div><div className="modal-actions"><button type="button" className="button secondary" onClick={onClose}>ยกเลิก</button><button className="button primary" type="submit" disabled={busy || !name.trim() || !ids.length}>{busy ? <Loader2 size={16} className="spin" /> : <Plus size={17} />}สร้างรอบสำรวจ</button></div></form></Modal>;
}

function RecordModal({ record, baseline, observations, rounds, evidence, onClose, onMeasure, publicReadOnly = false, editorUrl = DEFAULT_EDITOR_URL }: { publicReadOnly?: boolean; editorUrl?: string; record: BaselineRecord; baseline: Baseline; observations: Observation[]; rounds: Round[]; evidence: Evidence[]; onClose: () => void; onMeasure: () => void }) {
  return <Modal title={`ป้าย ${record.tag || 'ไม่ระบุ'} · ${record.species}`} subtitle={`${record.plotId} · รายการ ${record.id} · แถวต้นทาง ${record.row}`} onClose={onClose} wide><div className="modal-body"><div className="record-hero"><div className="record-tree-icon"><TreePine size={39} /></div><div><span className="eyebrow">BASELINE MEASUREMENT</span><h3>{number(record.dbhCm, 2)} <small>ซม. DBH</small></h3><p>ปีอ้างอิงแบบจำลอง {baseline.meta.baselineYearBE || 'ไม่ระบุ'} · ไม่ระบุวันที่วัดจริง</p></div><div className="record-carbon"><span>คาร์บอนตามไฟล์</span><strong>{number(record.stockTco2e, 4)}</strong><small>tCO₂e</small></div></div>{record.flags.length > 0 && <Banner kind="warn">{record.flags.map(flagText).join(' · ')}</Banner>}<div className="detail-grid"><div><h3>ข้อมูลต้นทาง</h3><dl className="definition-list"><dt>ชนิดไม้</dt><dd>{record.species}</dd><dt>ความหนาแน่นเนื้อไม้</dt><dd>{number(record.woodDensity, 4)}<small className="cell-sub">ค่าตามตาราง MWD; ต้นทางไม่ระบุหน่วย</small></dd><dt>ชีวมวลเหนือดิน</dt><dd>{number(record.agbKg, 3)} kg</dd><dt>ชีวมวลใต้ดิน</dt><dd>{number(record.bgbKg, 3)} kg</dd><dt>เครื่องหมายนับต้น</dt><dd>{record.countMarker === null ? 'ว่างในต้นฉบับ' : record.countMarker}</dd><dt>หมายเหตุต้นทาง</dt><dd>{record.note || '—'}</dd></dl></div><div><h3>ตรวจสอบย้อนกลับ</h3><div className="source-block"><FileSpreadsheet size={19} /><div><strong>{baseline.meta.fileName}</strong><p>ชีต {record.plotId} · แถว {record.row}</p><p>DBH: E{record.row} · หมายเลขป้าย: C{record.row}</p></div></div><p className="helper">รหัสรายการผูกกับชีตและแถวต้นทาง ต้องยืนยันป้ายและลำต้นจริงก่อนใช้ติดตามรายต้น</p></div></div>{publicReadOnly ? <Banner>ข้อมูลการวัดซ้ำและหลักฐานภาคสนามจัดการในพื้นที่สำรวจ ผู้มีสิทธิ์สามารถเปิดพื้นที่สำรวจเพื่อบันทึกผลวัด</Banner> : <><h3 className="subsection-title">ประวัติการวัดซ้ำ</h3>{observations.length ? <div className="measurement-history">{observations.map(o => <div key={o.id} className="history-entry"><span className="history-dot" /><div><strong>{rounds.find(r => r.id === o.roundId)?.name || 'รอบสำรวจ'}</strong><small>{dateLabel(o.observedOn)} · {o.observer}</small><p>{statusText[o.status]} · {o.dbhCm !== null ? `${number(o.dbhCm, 2)} ซม.` : 'ไม่ได้บันทึกขนาด'} · จุดวัด {number(o.pomM, 2)} ม.</p>{o.notes && <p className="muted">{o.notes}</p>}</div><span className="badge neutral">ฉบับ {o.version}</span></div>)}</div> : <p className="empty-inline">ยังไม่มีการวัดซ้ำสำหรับรายการนี้</p>}</>}{evidence.length > 0 && <div className="evidence-grid">{evidence.map(e => <a href={e.url} target="_blank" rel="noreferrer" key={e.id}><img src={e.url} alt={e.fileName} /><small>{e.fileName}</small></a>)}</div>}</div><div className="modal-actions"><button className="button secondary" onClick={onClose}>ปิด</button>{publicReadOnly ? <EditorLink editorUrl={editorUrl} /> : <button className="button primary" onClick={onMeasure}><Plus size={17} />บันทึกผลวัดใหม่</button>}</div></Modal>;
}

function MeasurementEditor({ record, round, observation, pending, evidence, onClose, onSave }: { record: BaselineRecord; round: Round; observation?: Observation; pending?: PendingObservation; evidence: Evidence[]; onClose: () => void; onSave: (input: ObservationInput, files: File[], next: boolean) => Promise<void> }) {
  const initial = pending?.payload || observation;
  const [status, setStatus] = useState<ObservationStatus>(initial?.status || 'alive'); const [inputType, setInputType] = useState<'dbh' | 'gbh'>(initial?.inputType || 'dbh'); const [raw, setRaw] = useState(initial?.rawValue?.toString() || ''); const [pom, setPom] = useState(initial?.pomM?.toString() || ''); const [date, setDate] = useState(initial?.observedOn || today()); const [observer, setObserver] = useState(initial?.observer || ''); const [notes, setNotes] = useState(initial?.notes || ''); const [identity, setIdentity] = useState(initial?.identityConfirmed || false); const [samePom, setSamePom] = useState(initial?.samePomConfirmed || false); const [photos, setPhotos] = useState<File[]>([]); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const dbh = raw ? Number(raw) / (inputType === 'gbh' ? Math.PI : 1) : null;
  async function save(next: boolean) {
    if (!observer.trim() || !date) { setError('ระบุผู้สำรวจและวันที่วัด'); return; }
    if (status === 'alive' && (dbh === null || !Number.isFinite(dbh) || dbh <= 0)) { setError('ระบุขนาดที่วัดเป็นจำนวนมากกว่า 0'); return; }
    if (pom && (!Number.isFinite(Number(pom)) || Number(pom) <= 0)) { setError('ระดับจุดวัดต้องมากกว่า 0 เมตร'); return; }
    if (status !== 'alive' && !notes.trim()) { setError('กรุณาบันทึกรายละเอียดหรือเหตุผลของสถานะนี้'); return; }
    setBusy(true); setError('');
    try { await onSave({ roundId: round.id, recordId: record.id, status, inputType, rawValue: status === 'alive' ? Number(raw) : null, pomM: pom ? Number(pom) : null, observedOn: date, observer: observer.trim(), notes: notes.trim(), identityConfirmed: identity, samePomConfirmed: samePom, expectedVersion: observation?.version || 0, operationId: createOperationId() }, photos, next); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); }
  }
  return <Modal title={`บันทึกผลวัด · ${record.tag || 'ไม่มีป้าย'}`} subtitle={`${round.name} · ${record.plotId} แถว ${record.row}`} onClose={onClose} wide><div className="modal-body"><div className="measurement-baseline"><span className="tree-symbol"><TreePine size={23} /></span><div><strong>{record.species}</strong><p>DBH เบสไลน์ {number(record.dbhCm, 2)} ซม. · ป้าย {record.tag || 'ไม่ระบุ'}</p></div><span className="code-chip">{record.id}</span></div>{record.flags.length > 0 && <Banner kind="warn">{record.flags.map(flagText).join(' · ')}</Banner>}{pending?.error && <Banner kind="warn">รายการรอส่งเดิมมีปัญหา: {pending.error} ตรวจและบันทึกอีกครั้งหลังโหลดข้อมูลล่าสุด</Banner>}<label className="form-label">สถานะที่พบ</label><div className="status-options">{Object.entries(statusText).map(([value, label]) => <button type="button" className={status === value ? 'selected' : ''} key={value} onClick={() => setStatus(value as ObservationStatus)}>{value === 'alive' ? <TreePine size={16} /> : value === 'not_found' ? <Search size={16} /> : value === 'dead' ? <TriangleAlert size={16} /> : <Info size={16} />}{label}</button>)}</div>{status === 'alive' && <div className="measurement-inputs"><label>วิธีอ่านขนาด<select value={inputType} onChange={e => setInputType(e.target.value as 'dbh' | 'gbh')}><option value="dbh">เส้นผ่านศูนย์กลาง (DBH)</option><option value="gbh">เส้นรอบวง (GBH)</option></select></label><label>{inputType === 'dbh' ? 'เส้นผ่านศูนย์กลาง' : 'เส้นรอบวง'} (ซม.) <span>*</span><input type="number" step="0.01" min="0.01" inputMode="decimal" placeholder="ค่าที่วัดครั้งนี้" value={raw} onChange={e => setRaw(e.target.value)} /></label><label>ระดับจุดวัด (เมตร)<input type="number" step="0.01" min="0.01" inputMode="decimal" placeholder="เช่น 1.30" value={pom} onChange={e => setPom(e.target.value)} /></label></div>}{status === 'alive' && inputType === 'gbh' && <p className="conversion-note">DBH ที่แปลงจากเส้นรอบวง ÷ π = <b>{number(dbh, 3)} ซม.</b> · ใช้เฉพาะการวัดที่จุดเดียวกัน</p>}<div className="form-two"><label>วันที่ตรวจวัด <span>*</span><input type="date" required value={date} onChange={e => setDate(e.target.value)} /></label><label>ผู้สำรวจ <span>*</span><input maxLength={120} placeholder="ชื่อผู้วัดหรือทีมสำรวจ" value={observer} onChange={e => setObserver(e.target.value)} /></label></div><div className="confirmation-box"><label><input type="checkbox" checked={identity} onChange={e => setIdentity(e.target.checked)} /><span>ยืนยันว่าเป็นต้น / ลำต้นเดียวกับรายการเบสไลน์นี้<small>ตรวจหมายเลขป้าย ตำแหน่ง และลักษณะต้นจริง</small></span></label><label><input type="checkbox" checked={samePom} onChange={e => setSamePom(e.target.checked)} /><span>ยืนยันจุดวัดและวิธีวัดเทียบกับเบสไลน์ได้<small>หากยังยืนยันไม่ได้ ให้เว้นไว้และอธิบายในหมายเหตุ</small></span></label></div><label className="form-label">หมายเหตุ / เหตุผล<textarea maxLength={3000} rows={3} value={notes} placeholder="จุดวัดเปลี่ยน ป้ายหลุด รากค้ำสูง หรือเหตุผลที่ยังยืนยันข้อมูลไม่ได้" onChange={e => setNotes(e.target.value)} /></label><div className="photo-upload"><div><Camera size={21} /><strong>หลักฐานภาพถ่าย</strong><small>รูปต้น ป้าย และจุดวัด · JPG, PNG, WebP สูงสุด 5 MB ต่อรูป</small></div><label className="button secondary small">เลือกรูป<input type="file" accept="image/jpeg,image/png,image/webp" multiple className="sr-only" onChange={e => { const files = Array.from(e.target.files || []); if (files.some(f => f.size > 5 * 1024 * 1024)) { setError('รูปภาพต้องมีขนาดไม่เกิน 5 MB ต่อรูป'); return; } setPhotos(files); }} /></label></div>{photos.length > 0 && <p className="helper">เตรียมแนบ {photos.length} รูป: {photos.map(p => p.name).join(', ')}</p>}{evidence.length > 0 && <div className="evidence-grid">{evidence.map(e => <a key={e.id} href={e.url} target="_blank" rel="noreferrer"><img src={e.url} alt={e.fileName} /></a>)}</div>}{error && <Banner kind="warn">{error}</Banner>}<p className="helper">บันทึกฉบับร่างได้แม้ยังยืนยันไม่ครบ การเปรียบเทียบคาร์บอนจะใช้เฉพาะรายการที่ผ่านเงื่อนไข</p></div><div className="modal-actions"><button className="button secondary" disabled={busy} onClick={() => save(false)}>{busy ? <Loader2 className="spin" size={16} /> : <Save size={16} />}บันทึก</button><button className="button primary" disabled={busy} onClick={() => save(true)}>บันทึกและถัดไป <ArrowRight size={16} /></button></div></Modal>;
}

function PublicSurveyView({ editorUrl, samplePlotCount, measurementCount }: { editorUrl: string; samplePlotCount: number; measurementCount: number }) {
  return <>
    <section className="panel public-survey-panel">
      <span className="public-survey-icon"><ClipboardList size={34} /></span>
      <div className="eyebrow">FIELD SURVEY WORKSPACE</div>
      <h2>พื้นที่บันทึกผลสำรวจ</h2>
      <p>เว็บไซต์สาธารณะนี้ใช้เปิดดู ตรวจสอบ และดาวน์โหลดข้อมูลเบสไลน์ การสร้างรอบสำรวจและบันทึกผลวัดซ้ำอยู่ในพื้นที่สำรวจสำหรับผู้มีสิทธิ์เข้าถึง</p>
      <div className="public-survey-stats"><span><MapPin size={17} /><b>{number(samplePlotCount)}</b> แปลงตัวอย่าง</span><span><Trees size={17} /><b>{number(measurementCount)}</b> รายการเบสไลน์</span></div>
      <EditorLink editorUrl={editorUrl}>เปิดพื้นที่สำรวจ</EditorLink>
      <small>เปิดผ่านบัญชี ChatGPT ที่มีสิทธิ์เข้าถึงพื้นที่สำรวจ</small>
    </section>
    <div className="quality-cards public-survey-steps">
      <article><span className="quality-number">01</span><h3>กำหนดรอบและแปลง</h3><p>เลือกรายการแปลงที่จะกลับไปวัด พร้อมระบุวันที่และแผนงานสำรวจ</p></article>
      <article><span className="quality-number">02</span><h3>บันทึกผลที่พบจริง</h3><p>บันทึก DBH หรือเส้นรอบวง สถานะ จุดวัด ผู้สำรวจ และหลักฐานภาพถ่าย</p></article>
      <article><span className="quality-number">03</span><h3>ตรวจสอบและออกรายงาน</h3><p>ตรวจความครบถ้วนและเงื่อนไขการจับคู่ ก่อนล็อกชุดสำรวจเพื่อใช้อ้างอิง</p></article>
    </div>
    <Banner>รอบสำรวจ ผลวัดซ้ำ และภาพถ่ายในพื้นที่สำรวจไม่ได้เผยแพร่ผ่านหน้านี้</Banner>
  </>;
}

function QualityView({ baseline, onRecord, onPlot }: { baseline: Baseline; onRecord: (id: string) => void; onPlot: (id: string) => void }) {
  const [filter, setFilter] = useState(''); const [page, setPage] = useState(0);
  const flags = [...new Set(baseline.records.flatMap(r => r.flags))];
  const records = baseline.records.filter(r => r.flags.length && (!filter || r.flags.includes(filter)));
  const sourceIssues: Record<string, unknown>[] = [...baseline.qa.issues, ...baseline.meta.flags.filter(flag => !baseline.qa.issues.some(issue => issue.code === flag)).map(flag => ({ code: flag, scope: 'dataset', message: flagText(flag), severity: 'warning' }))];
  const uniqueIssues = Array.from(new Map(sourceIssues.map(issue => [`${String(issue.code || issue.message)}:${String(issue.scope || 'dataset')}`, issue])).values());
  return <><div className="quality-intro"><span className="quality-intro-icon"><ShieldCheck size={31} /></span><div><h2>รักษาข้อมูลเดิม เพิ่มความมั่นใจทีละขั้น</h2><p>ข้อสังเกตต่อไปนี้มาจากการตรวจไฟล์ต้นทาง ข้อมูลยังคงเก็บตามต้นฉบับเพื่อให้ตรวจย้อนกลับได้</p></div><span className="badge amber">รอยืนยันภาคสนาม</span></div><div className="quality-cards"><article><span className="quality-number">01</span><h3>รายการวัด ≠ จำนวนต้น</h3><p>พบ {number(baseline.meta.measurementCount)} แถวการวัด และเครื่องหมายนับต้น {number(baseline.meta.sourceTreeCount)} ต้น มีหมายเลขป้ายซ้ำ {number(Number(baseline.qa.duplicateTagGroups))} กลุ่ม ครอบคลุม {number(baseline.qa.counts.DUPLICATE_TAG_IN_PLOT)} รายการ</p></article><article><span className="quality-number">02</span><h3>วันวัดและจุดวัดเดิม</h3><p>ปี 2567 เป็นปีอ้างอิงแบบจำลอง ไม่ใช่วันที่วัดจริง ยังต้องยืนยันวันวัดและระดับจุดวัดรายต้นก่อนเปรียบเทียบ</p></article><article><span className="quality-number">03</span><h3>ตรวจหน่วยและสูตร</h3><p>เก็บ DBH และผลคำนวณตามต้นทาง รายการที่ความหมายหรือสูตรไม่ชัดเจนจะแสดงข้อสังเกตไว้</p></article></div>
    <section className="panel"><SectionHead title="ข้อสังเกตจากไฟล์ต้นทาง" action={<span className="badge neutral">{uniqueIssues.length} รายการ</span>} /><div className="issue-list">{uniqueIssues.map((issue, i) => <div className="issue-item" key={i}>{issue.severity === 'warning' ? <TriangleAlert size={17} /> : <Info size={17} />}<p>{String(issue.message || issue.description || issue.title || flagText(String(issue.code || '')))}</p></div>)}</div></section>
    <section className="panel"><SectionHead title="แปลงที่มีข้อสังเกต" /><div className="plot-quality-list">{baseline.plots.filter(p => p.flags.length).map(p => <button key={p.id} onClick={() => onPlot(p.id)}><span className="code-chip">{p.id}</span><p>{p.flags.map(flagText).join(' · ')}</p><ArrowUpRight size={16} /></button>)}</div></section>
    <section className="panel no-padding"><div className="table-caption"><div><strong>ตรวจรายการวัดต้นทาง</strong><span>{number(records.length)} รายการ</span></div><select value={filter} onChange={e => { setFilter(e.target.value); setPage(0); }} aria-label="ประเภทข้อสังเกต"><option value="">ทุกข้อสังเกต</option>{flags.map(f => <option key={f} value={f}>{flagText(f)} · {number(baseline.qa.counts[f])}</option>)}</select></div><div className="table-scroll"><table className="data-table"><thead><tr><th>แหล่งข้อมูล</th><th>หมายเลขป้าย</th><th>ชนิดไม้</th><th>ข้อสังเกต</th><th /></tr></thead><tbody>{records.slice(page * 30, page * 30 + 30).map(r => <tr key={r.id} onClick={() => onRecord(r.id)}><td><strong>{r.plotId}</strong><small className="cell-sub">แถว {r.row}</small></td><td>{r.tag || '—'}</td><td>{r.species}</td><td className="issue-cell">{r.flags.map(flagText).join(' · ')}</td><td><ChevronRight size={16} /></td></tr>)}</tbody></table></div><div className="pagination"><span>{number(records.length)} รายการที่มีข้อสังเกต</span><div><button className="icon-button" disabled={!page} onClick={() => setPage(p => p - 1)} aria-label="หน้าก่อน"><ChevronLeft size={18} /></button><span>{page + 1} / {Math.max(1, Math.ceil(records.length / 30))}</span><button className="icon-button" disabled={(page + 1) * 30 >= records.length} onClick={() => setPage(p => p + 1)} aria-label="หน้าถัดไป"><ChevronRight size={18} /></button></div></div></section></>;
}

type ReportData = { round: Round; observations: Observation[]; evidence: Evidence[]; summary: { expected: number; recorded: number; coverage: number; pairedCount: number; pairedBaselineTco2e: number; pairedCurrentTco2e: number; pairedDeltaTco2e: number; meanDbhChangeCm: number | null; statusCounts: Record<string, number>; issues: unknown[] }; source: { fileName: string; sha256: string }; createdAt: string; locked: boolean };
function ReportsView({ baseline, state, selectedRoundId, onSelectRound, pending, refreshState, notify, publicReadOnly = false }: { publicReadOnly?: boolean; baseline: Baseline; state: AppState; selectedRoundId: string; onSelectRound: (id: string) => void; pending: Pending[]; refreshState: () => Promise<AppState>; notify: (message: string) => void }) {
  const [report, setReport] = useState<ReportData | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [lockConfirm, setLockConfirm] = useState(false);
  const currentRound = publicReadOnly ? undefined : state.rounds.find(r => r.id === selectedRoundId);
  const round = report?.round.id === selectedRoundId ? report.round : currentRound;
  useEffect(() => { let alive = true; setReport(null); setBusy(false); if (publicReadOnly || !currentRound) return; setBusy(true); setError(''); api<ReportData>(`/api/reports/${currentRound.id}`).then(r => { if (alive) setReport(r); }).catch(e => { if (alive) { setError(errorMessage(e)); setReport(null); } }).finally(() => { if (alive) setBusy(false); }); return () => { alive = false; }; }, [publicReadOnly, currentRound?.id, currentRound?.version, state.observations]);
  const summary = report?.summary; const hasPending = pending.some(p => (p.kind === 'observation' ? p.payload.roundId : p.roundId) === round?.id);
  async function lock() { if (publicReadOnly || !round) return; setBusy(true); try { await api(`/api/rounds/${round.id}/lock`, { method: 'POST', body: JSON.stringify({ expectedVersion: round.version }) }); await refreshState(); setLockConfirm(false); notify('ล็อกชุดสำรวจและเก็บรายงานฉบับอ้างอิงแล้ว'); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <><div className="report-toolbar"><div><FileText size={20} /><select aria-label="เลือกชุดรายงาน" value={round?.id || ''} onChange={e => onSelectRound(e.target.value)}><option value="">รายงานข้อมูลเบสไลน์</option>{state.rounds.map(r => <option value={r.id} key={r.id}>{r.name}{r.status === 'locked' ? ' · ล็อกแล้ว' : ' · ฉบับร่าง'}</option>)}</select></div><div><a className="button secondary small" href={publicReadOnly ? "./source-baseline.xlsx" : "/source-baseline.xlsx"} download><FileSpreadsheet size={15} />Excel ต้นฉบับ</a><CsvButton publicReadOnly={publicReadOnly} roundId={round?.id} /><CsvButton publicReadOnly={publicReadOnly} roundId={round?.id} type="json" /><button className="button primary small" onClick={() => window.print()}><FileText size={15} />พิมพ์ / PDF</button></div></div>{error && <Banner kind="warn">{error}</Banner>}{busy && <div className="loading-inline"><Loader2 className="spin" size={19} />กำลังเตรียมรายงาน…</div>}
    <article className="report-paper" id="mrv-report"><header className="report-header"><div><div className="report-brand"><Trees size={24} /> Mangrove MRV</div><span className="eyebrow">MONITORING · REPORTING · VERIFICATION</span></div><div><span className={`badge ${report?.locked ? 'green' : 'neutral'}`}>{round ? report?.locked ? 'ล็อกชุดข้อมูลแล้ว' : 'รายงานฉบับร่าง' : 'ข้อมูลเบสไลน์ต้นทาง'}</span><small>MOC2 / VSD</small></div></header><h2>{round ? `รายงานการสำรวจ: ${round.name}` : 'รายงานสรุปข้อมูลเบสไลน์'}</h2><p className="report-subtitle">{round ? `${dateLabel(round.date)} · ${round.plotIds.length} แปลงตัวอย่าง` : `ปีอ้างอิงแบบจำลอง ${baseline.meta.baselineYearBE || 'ไม่ระบุ'} · ${baseline.plots.length} แปลงตัวอย่าง · ${number(baseline.meta.sampleAreaRai, 1)} ไร่`}</p>
    {!round && <><div className="report-metric-row"><div><span>รายการวัดในไฟล์</span><strong>{number(baseline.meta.measurementCount)}</strong></div><div><span>ต้นตามเครื่องหมายนับ</span><strong>{number(baseline.meta.sourceTreeCount)}</strong></div><div><span>คาร์บอนรวมในแปลงตัวอย่าง</span><strong>{number(baseline.plots.reduce((s, p) => s + p.sourceStockTco2e, 0), 3)} <small>tCO₂e</small></strong></div></div><h3>1. ขอบเขตและความหมายของข้อมูล</h3><p>ข้อมูลนี้เป็นรายการตรวจวัดจากแปลงตัวอย่างตามไฟล์ต้นทาง จำนวนรายการอาจต่างจากจำนวนต้น เนื่องจากรายการหลายลำต้น ป้ายซ้ำ และการนับต้นในไฟล์ ปี {baseline.meta.baselineYearBE || 'ไม่ระบุ'} จาก Total GHG!A2 เป็นปีอ้างอิงแบบจำลอง ต้นฉบับไม่ระบุวันที่ตรวจวัดจริงรายต้น</p><table className="report-table"><thead><tr><th>แปลง</th><th>จังหวัด</th><th>ชั้นภูมิ</th><th>พื้นที่ (ไร่)</th><th>รายการ</th><th>คาร์บอน (tCO₂e)</th></tr></thead><tbody>{baseline.plots.map(p => <tr key={p.id}><td>{p.id}</td><td>{p.province}</td><td>{p.stratum}</td><td>{number(p.areaRai, 1)}</td><td>{number(p.recordCount)}</td><td>{number(p.sourceStockTco2e, 3)}</td></tr>)}</tbody></table><h3>2. การประมาณระดับโครงการในต้นฉบับ</h3><p>ไฟล์ระบุพื้นที่เข้าร่วมโครงการ {number(baseline.meta.projectAreaRai, 2)} ไร่ และปริมาณคาร์บอนกรณีฐานที่ขยายผล {number(baseline.meta.projectBaselineTco2e, 3)} tCO₂e ตัวเลขนี้แยกจากยอดคาร์บอนในพื้นที่แปลงตัวอย่างจริง</p><Banner kind="warn">ค่าการเพิ่มพูน {number(baseline.meta.projectionMaiTco2eRaiYear, 1)} tCO₂e/ไร่/ปี ในไฟล์เป็นสมมติฐานคาดการณ์ ไม่ใช่ผลวัดซ้ำหรือเครดิตที่รับรองแล้ว</Banner></>}
    {round && report && summary && <><div className="report-metric-row"><div><span>รายการที่บันทึก</span><strong>{number(summary.recorded)} / {number(summary.expected)}</strong></div><div><span>จับคู่เทียบคาร์บอนได้</span><strong>{number(summary.pairedCount)} <small>รายการ</small></strong></div><div><span>ความเปลี่ยนแปลงเฉพาะคู่ที่เทียบได้</span><strong>{summary.pairedCount ? number(summary.pairedDeltaTco2e, 4) : '—'} <small>tCO₂e</small></strong></div></div><h3>1. ความครบถ้วนการสำรวจ</h3><table className="report-table"><tbody>{Object.entries(statusText).map(([status, label]) => <tr key={status}><td>{label}</td><td>{number(summary.statusCounts[status] || 0)} รายการ</td></tr>)}<tr><td>ยังไม่มีผลบันทึก</td><td>{number(summary.expected - summary.recorded)} รายการ</td></tr></tbody></table><Banner kind={summary.recorded === summary.expected ? 'good' : 'warn'}>{summary.recorded === summary.expected ? 'บันทึกสถานะครบตามรายการในขอบเขตรอบสำรวจ' : 'ข้อมูลยังไม่ครบทั้งรอบ ผลนี้เป็นข้อมูลระหว่างสำรวจ'} · การจับคู่ใช้เฉพาะต้นที่ยืนยันตัวตน จุดวัด และข้อมูลที่จำเป็นครบ</Banner><h3>2. ผลเปรียบเทียบเฉพาะรายการที่เทียบกันได้</h3><table className="report-table"><tbody><tr><td>คาร์บอนเบสไลน์ของคู่ที่เทียบได้</td><td>{summary.pairedCount ? number(summary.pairedBaselineTco2e, 4) : '—'} tCO₂e</td></tr><tr><td>คาร์บอนรอบนี้ของคู่ที่เทียบได้</td><td>{summary.pairedCount ? number(summary.pairedCurrentTco2e, 4) : '—'} tCO₂e</td></tr><tr><td>การเปลี่ยน DBH เฉลี่ยของคู่ที่เทียบได้</td><td>{number(summary.meanDbhChangeCm, 3)} ซม.</td></tr></tbody></table><p>การเปรียบเทียบนี้ใช้เฉพาะรายการที่วัดและจับคู่ได้ ไม่ใช่การเปลี่ยนคาร์บอนทั้งแปลงหรือทั้งโครงการ และไม่รวมผลการตายหรือแหล่งสะสมคาร์บอนอื่นโดยอัตโนมัติ</p>{summary.issues?.length > 0 && <><h3>3. ข้อสังเกตของชุดสำรวจ</h3><ul className="report-issues">{summary.issues.slice(0, 20).map((issue, i) => <li key={i}>{typeof issue === 'string' ? issue : String((issue as Record<string, unknown>).message || (issue as Record<string, unknown>).code || JSON.stringify(issue))}</li>)}</ul></>}{round.notes && <p><b>หมายเหตุรอบสำรวจ:</b> {round.notes}</p>}</>}
    <h3>วิธีคำนวณและแหล่งที่มา</h3><p>การคำนวณตามสูตรที่พบในไฟล์: AGB = 0.251 × ρ × DBH<sup>2.46</sup> และ BGB = 0.199 × ρ<sup>0.899</sup> × DBH<sup>2.22</sup> โดย ρ คือความหนาแน่นเนื้อไม้ และ DBH มีหน่วยเซนติเมตร ใช้ carbon fraction 0.4715 และแปลงคาร์บอนเป็น CO₂ ด้วย 44/12 ผลจากชีวมวลกิโลกรัมแปลงเป็นตันด้วย 1,000</p><p>ขอบเขตผลนี้คือคาร์บอนในชีวมวลต้นไม้ตามข้อมูลและสมการดังกล่าว การใช้ยื่น MRV ต้องยืนยันข้อมูลต้นทาง ความเหมาะสมของสมการ ขอบเขตบัญชี และวิธีของโครงการก่อน</p><div className="report-source"><FileSpreadsheet size={19} /><div><strong>{report?.source.fileName || baseline.meta.fileName}</strong><p>SHA-256: {report?.source.sha256 || baseline.meta.sha256}</p><p>{report?.locked ? `ชุดข้อมูลล็อกเมื่อ ${dateLabel(report.createdAt)}` : 'สถานะ: ข้อมูลสำหรับตรวจและจัดทำรายงาน'}</p></div></div><footer className="report-footer"><span>จัดทำด้วย Mangrove MRV</span><span>เอกสารประกอบการติดตาม · ไม่ใช่หนังสือรับรองเครดิต</span></footer></article>
    {round && round.status !== 'locked' && <div className="lock-bar"><div><LockKeyhole size={21} /><div><strong>ล็อกชุดสำรวจเพื่อใช้อ้างอิง</strong><p>เก็บผลวัด วิธีคำนวณ และหลักฐานเป็นฉบับเดียวกัน เมื่อครบเงื่อนไขการตรวจ</p></div></div><button className="button primary" disabled={busy || hasPending || !summary || summary.recorded !== summary.expected} onClick={() => setLockConfirm(true)}>ตรวจและล็อกชุดข้อมูล</button></div>}{hasPending && <Banner kind="warn">มีรายการของรอบนี้ที่ยังอยู่ในเครื่อง กรุณาส่งข้อมูลก่อนสร้างชุดอ้างอิง</Banner>}{lockConfirm && <Modal title="ล็อกชุดสำรวจนี้?" subtitle={round?.name} onClose={() => setLockConfirm(false)}><div className="modal-body"><p>เมื่อยืนยัน ผลวัดและหลักฐานในรอบนี้จะเป็นฉบับอ้างอิงและอ่านอย่างเดียว รายงานนี้ยังเป็นข้อมูลประกอบการติดตาม MRV</p><Banner>การล็อกเป็นการยืนยันภายในระบบ ไม่ใช่การรับรองคาร์บอนเครดิต</Banner></div><div className="modal-actions"><button className="button secondary" onClick={() => setLockConfirm(false)}>กลับไปตรวจ</button><button className="button primary" disabled={busy} onClick={lock}><LockKeyhole size={16} />ยืนยันล็อกชุดสำรวจ</button></div></Modal>}</>;
}
